SLIDES=[]
def add(title, sec, layout, items, takeaway, notes, refs='', visual='', cue=''):
    i=len(SLIDES)+1
    SLIDES.append(dict(n=i,title=title,sec=sec,layout=layout,items=items,takeaway=takeaway,notes=notes,refs=refs,visual=visual,cue=cue,part=1 if i<=5 else 2 if i<=19 else 3 if i<=26 else 4,speaker='甲' if i<=16 else '乙'))

add('合理用药：给宿舍药箱上堂课',45,'cover',['会选药 · 看成分 · 避误区','苏州大学｜选修课课堂展示','主讲：同学甲 / 同学乙'], '把每一次“吃什么药”，变成有依据的选择。',
'''甲：大家好。今天我们聊一个进入大学后越来越需要自己做决定的问题：身体不舒服时，药到底该怎么用？离开父母的提醒，宿舍药箱、室友推荐和手机搜索，可能成了我们的第一反应。但名字熟悉，不代表适合自己；药吃得多，也不代表好得快。接下来我们用四类校园情境和几轮举手选择，练习几个能直接用上的判断。我们不考药名，也不背剂量表，目标是学会看什么、问什么，以及什么时候应该就医。''',visual='蓝红白宿舍桌面插画：药盒、书本、水杯；原创可编辑矢量元素。',cue='甲主讲；乙操作翻页。')
add('室友感冒了，你先做哪一步？',90,'quiz',['A 用上次的剩药，沿用当时吃法', 'B 拍清楚药盒，先核对再作决定', 'C 按最主要症状，先挑一盒试试'],'举手选择 A / B / C｜暂不揭晓',
'甲：小苏流鼻涕、喉咙不舒服，明天还有课。药箱里有上次剩下的药，室友也递来一盒。沿用经验、先核信息、按症状挑药，三个方案都像是在解决问题。信息还不完整时，你选哪一个第一步？\n【静默10秒；A、B、C依次举手，各约5秒】\n甲：先保留选择。上次有效不代表这次适用，包装上的症状描述也不能代替核对；下一页看判断需要哪些信息。','',visual='三张等宽选择卡；不突出正确选项。',cue='10秒阅读＋三轮举手约25秒；不追问个人用药史。')
add('合理用药，要同时过四关',60,'four',['安全｜关注禁忌与不良反应','有效｜针对真正需要解决的问题','经济｜避免不必要的花费','适宜｜适合这个人、这个时机'], '刚才选 B：先了解，再决定。',
'''甲：合理用药可以用四个词记住：安全、有效、经济、适宜。安全不是承诺任何药都没有风险，而是识别禁忌和可能的不良反应。有效，是药物针对的问题与实际需要相符。经济，是在满足治疗需要的前提下，避免不必要的药物和花费。适宜，则提醒我们，同一个药对室友合适，对自己不一定合适，年龄、过敏史、正在使用的其他药物，都可能影响选择。所以开场选B，是先把这些信息补齐，而不是看到一个症状就直接往药箱里伸手。''','S1',visual='四象限原则卡；每格一个关键词和一个简短解释。')
add('鼻子舒服了，为什么上课却犯困？',60,'target',['鼻部｜组胺参与部分过敏反应', '脑内｜组胺信号也参与维持清醒', '用药前｜查嗜睡提示，说清上课与通勤需求'],'症状缓解，不代表没有其他影响｜先查嗜睡提示',
'甲：小苏吃了抗过敏药，鼻子舒服了，上课却开始犯困。药明明在起作用，怎么还会影响精神？先看图里的两个位置：组胺在鼻部参与部分过敏反应，在脑内也参与维持清醒。部分抗组胺药能进入脑内，影响相关信号，因此可能在缓解过敏症状的同时让人困倦。这就是生物课里的“信号传递”在生活中的一个例子：同一种信号物质，在不同位置可以参与不同功能。不是所有抗过敏药都一样，也不是人人都会困。对我们有用的结论是：选择药物时，不只问能不能缓解症状，还要查嗜睡提示，向药师说清白天有课或需要通勤；已经困倦时，避免驾驶、骑车等高风险活动。后面再展开解释这个机制。','S8',visual='两幅同一角色的动漫分镜：鼻部症状缓解、课堂犯困；对白独立排版，图下保留简短机制说明，不重复设置场景小标题。',cue='')
